import{_ as t,o,c as a,ag as d}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"Export to Markdown","description":"","frontmatter":{},"headers":[],"relativePath":"guide/export2markdown.md","filePath":"guide/export2markdown.md","lastUpdated":1786671054000}'),l={name:"guide/export2markdown.md"};function r(i,e,n,s,c,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="export-to-markdown" tabindex="-1">Export to Markdown <a class="header-anchor" href="#export-to-markdown" aria-label="Permalink to &quot;Export to Markdown&quot;">​</a></h1><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="method-1-right-click-export" tabindex="-1">Method 1: Right-Click Export <a class="header-anchor" href="#method-1-right-click-export" aria-label="Permalink to &quot;Method 1: Right-Click Export&quot;">​</a></h3><ol><li>Open a file containing APIs in your project, or select files/folders in the IDEA project panel</li><li>Right-click on the file content or folder</li><li>Select <code>ExportMarkdown</code> to export all APIs in the file or folder</li></ol><h3 id="method-2-shortcut-export" tabindex="-1">Method 2: Shortcut Export <a class="header-anchor" href="#method-2-shortcut-export" aria-label="Permalink to &quot;Method 2: Shortcut Export&quot;">​</a></h3><ol><li>Open a file containing APIs in your project, or select files/folders in the IDEA project panel</li><li>Use shortcut <code>Alt + Shift + E</code> (Windows/Linux) or <code>Ctrl + E</code> (macOS)</li><li>Select the APIs to export, choose <code>Markdown</code> as the export channel</li><li>Click the ✔ button or press Enter to complete the export</li></ol><h2 id="markdown-settings" tabindex="-1">Markdown Settings <a class="header-anchor" href="#markdown-settings" aria-label="Permalink to &quot;Markdown Settings&quot;">​</a></h2><ul><li><strong>outputDemo</strong>: Generate a response demo for each API when exporting Markdown</li><li><strong>outputCharset</strong>: Select the character set for Markdown export. Try changing this if exported documents show garbled text</li></ul><p>See <a href="/settings/ide-setting">IDE Settings</a> for more details.</p><h2 id="customizing-the-template" tabindex="-1">Customizing the Template <a class="header-anchor" href="#customizing-the-template" aria-label="Permalink to &quot;Customizing the Template&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">New in v3.2.0</p><p>Free-form Markdown export templates with internationalization (i18n) and remote source support landed in v3.2.0 (#1411). The persistent Markdown settings tab and the <code>markdown.template*</code> config rules below describe the full system.</p></div><p>When you trigger a Markdown export, EasyYapi opens a dialog that lets you override the output location and file name for this export. The template used to render the document is configured on the persistent <strong>Markdown</strong> settings tab (<kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; <kbd>Markdown</kbd>) and is reused across every export.</p><p>The export dialog exposes the following fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Output Directory</td><td>Target folder for the generated <code>.md</code> file. Blank uses the default output directory.</td></tr><tr><td>File Name</td><td>Output file name (without extension). Blank uses the default name.</td></tr></tbody></table><p>The following template fields live on the persistent Markdown settings tab and are reused across every export:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Template File</td><td>Path to a local template file (<code>.tpl</code> or <code>.md.tpl</code>).</td></tr><tr><td>Template URL</td><td>Remote <code>http(s)</code> URL serving a template. Responses are cached for 10 minutes; redirects are <strong>not</strong> followed.</td></tr><tr><td>Language</td><td>Combo box of bundled locale templates (e.g. <code>zh-CN</code>, <code>ja</code>, <code>en</code>). Selecting a bundled locale renders the document with that locale&#39;s template.</td></tr><tr><td>Show inline template</td><td>Reveals a multi-line text area for entering template content directly.</td></tr><tr><td>Copy default template</td><td>Copies the bundled default template into the inline area so you can edit it as a starting point.</td></tr></tbody></table><h3 id="template-resolution-order" tabindex="-1">Template Resolution Order <a class="header-anchor" href="#template-resolution-order" aria-label="Permalink to &quot;Template Resolution Order&quot;">​</a></h3><p>The resolver walks the tiers below; the <strong>first non-blank tier that succeeds wins</strong>. A tier that is blank or fails (missing file, HTTP error, oversize response) is skipped and the next tier is tried.</p><ol><li><strong>Inline template</strong> from the Markdown settings tab (the multi-line text area).</li><li><strong>Local template file</strong> from the Markdown settings tab (Template File field).</li><li><strong>Remote template URL</strong> from the Markdown settings tab (Template URL field).</li><li>The <strong><code>markdown.template</code> config rule</strong>. Its value is auto-detected: <ul><li>an <code>http(s)</code> URL is fetched remotely,</li><li>a single-line path is read as a local file,</li><li>anything else (multi-line text or content using double-curly-brace placeholders) is treated as inline template content.</li></ul></li><li><strong>Convention-based project file</strong> <code>&lt;project&gt;/.easyapi/markdown.tpl</code>, if it exists. This lets a team share a template by simply committing the file — no config key needed.</li><li>The <strong>bundled locale template</strong> selected by the <code>markdown.template.language</code> config rule <strong>or</strong> the Language combo box (combo box takes precedence).</li><li>The <strong>bundled <code>default.md.tpl</code></strong> as the floor — always present.</li></ol><div class="tip custom-block"><p class="custom-block-title">Template placeholders use double-curly braces</p><p>Template content interpolates variables using double-curly-brace placeholders. When you author Markdown <strong>documentation prose</strong> (like this page), never write the literal opening braces side by side — VitePress/Vue interprets that sequence as Vue interpolation and the build will fail. Refer to them as &quot;double-curly-brace placeholders&quot; in prose instead.</p></div><h3 id="config-rules" tabindex="-1">Config Rules <a class="header-anchor" href="#config-rules" aria-label="Permalink to &quot;Config Rules&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>Description</th></tr></thead><tbody><tr><td><code>markdown.template</code></td><td>Auto-detected template source (remote URL, local file path, or inline content). Replaces the legacy <code>markdown.template.file</code> / <code>markdown.template.url</code> / inline <code>markdown.template</code> keys, which are merged into this single key.</td></tr><tr><td><code>markdown.template.language</code></td><td>BCP-47 locale tag (e.g. <code>zh-CN</code>) selecting a bundled locale template. BCP-47 fallback applies when the exact tag is not bundled.</td></tr><tr><td><code>markdown.template.url.ttl.seconds</code></td><td>Cache TTL for remote template fetches. Default: <code>600</code> (10 minutes).</td></tr><tr><td><code>markdown.template.url.max.bytes</code></td><td>Maximum response size for a remote template fetch. Default: <code>1048576</code> (1 MiB).</td></tr></tbody></table><p>::: note Legacy keys merged The legacy separate keys <code>markdown.template.file</code>, <code>markdown.template.url</code> and the inline form of <code>markdown.template</code> are merged into the single <code>markdown.template</code> key (tier 4). The value is auto-detected as a remote URL when it starts with <code>http://</code> or <code>https://</code>, otherwise it is treated as a local file path, falling back to inline content. :::</p><h3 id="bundled-locales" tabindex="-1">Bundled Locales <a class="header-anchor" href="#bundled-locales" aria-label="Permalink to &quot;Bundled Locales&quot;">​</a></h3><p>EasyYapi ships localized templates for the following locales (the <code>en</code> default uses the bundled <code>default.md.tpl</code>):</p><p><code>zh-CN</code>, <code>zh-TW</code>, <code>zh</code>, <code>ja</code>, <code>ko</code>, <code>es</code>, <code>fr</code>, <code>de</code>, <code>ru</code>, <code>pt-BR</code>, <code>pt</code>, <code>it</code>, <code>ar</code>, <code>hi</code>, <code>vi</code>, <code>id</code>, <code>tr</code>, <code>pl</code>, <code>uk</code>, <code>nl</code>, <code>th</code>, <code>en</code>.</p>',26)])])}const u=t(l,[["render",r]]);export{m as __pageData,u as default};
